using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Uses constructor injection for HttpClient and ILogger.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Get a user's profile by their numeric ID.")]
    public async Task<string> GetUser(
        [Description("The user ID (1-10)")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var json = await httpClient.GetStringAsync($"/users/{userId}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("List all posts by a specific user.")]
    public async Task<string> GetUserPosts(
        [Description("The user ID to fetch posts for")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching posts for user {UserId}", userId);
        var json = await httpClient.GetStringAsync($"/posts?userId={userId}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("Create a new post. Returns the created post with its assigned ID.")]
    public async Task<string> CreatePost(
        [Description("The author's user ID")] int userId,
        [Description("The post title")] string title,
        [Description("The post body text")] string body,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating post for user {UserId}", userId);
        var payload = new { userId, title, body };
        var response = await httpClient.PostAsJsonAsync("/posts", payload, cancellationToken);
        response.EnsureSuccessStatusCode();
        var result = await response.Content.ReadAsStringAsync(cancellationToken);
        return result;
    }

    [McpServerTool, Description("Search posts by keyword in the title. Returns matching posts.")]
    public async Task<string> SearchPosts(
        [Description("Keyword to search for in post titles")] string keyword,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching posts for keyword '{Keyword}'", keyword);
        var json = await httpClient.GetStringAsync("/posts", cancellationToken);
        var posts = JsonSerializer.Deserialize<JsonElement[]>(json);
        var matches = posts?
            .Where(p => p.GetProperty("title").GetString()?
                .Contains(keyword, StringComparison.OrdinalIgnoreCase) == true)
            .ToArray() ?? [];
        return JsonSerializer.Serialize(matches, JsonOptions);
    }
}

